"""Bahasa Indonesia — Al-Qur'an (quran_001 … quran_080)."""

T = {
"quran_001": ("Apa nama surah pertama dalam Al-Qur'an?", ["Al-Fatihah", "Al-Baqarah", "Al-Ikhlas", "An-Nas"], "Al-Fatihah, «Pembukaan», adalah surah pertama dalam Al-Qur'an."),
"quran_002": ("Berapa jumlah surah dalam Al-Qur'an?", ["114", "99", "100", "120"], "Al-Qur'an terdiri dari 114 surah."),
"quran_003": ("Apa surah terpanjang dalam Al-Qur'an?", ["Al-Baqarah", "Al-Fatihah", "Al-Kautsar", "Al-'Ashr"], "Al-Baqarah adalah surah terpanjang dalam Al-Qur'an, dengan 286 ayat."),
"quran_004": ("Apa surah terpendek dalam Al-Qur'an?", ["Al-Kautsar", "Al-Ikhlas", "Al-'Ashr", "An-Nashr"], "Al-Kautsar, dengan 3 ayat, adalah surah terpendek dalam Al-Qur'an."),
"quran_005": ("Dalam bahasa apakah Al-Qur'an diturunkan?", ["Arab", "Aram", "Ibrani", "Persia"], "Al-Qur'an menyatakan dengan jelas bahwa ia diturunkan dalam bahasa Arab."),
"quran_006": ("Apa nama surah ke-19, yang dinamai menurut ibu Nabi Isa?", ["Maryam", "Yusuf", "Al-Kahfi", "Thaha"], "Surah ke-19 Al-Qur'an bernama Maryam, menurut nama ibu Nabi Isa."),
"quran_007": ("Apa sebutan untuk sebuah bab dalam Al-Qur'an?", ["Surah", "Hadis", "Juz", "Tafsir"], "Al-Qur'an dibagi menjadi bab-bab yang disebut surah."),
"quran_008": ("Apa sebutan untuk satu kalimat wahyu dalam Al-Qur'an?", ["Ayat", "Surah", "Hadis", "Rukuk"], "Setiap kalimat dalam Al-Qur'an disebut ayat, yang berarti «tanda»."),
"quran_009": ("Surah apa yang wajib dibaca pada setiap rakaat salat?", ["Al-Fatihah", "Al-Ikhlas", "Al-Kautsar", "Al-Fil"], "Membaca Al-Fatihah adalah rukun salat yang diriwayatkan dalam hadis sahih."),
"quran_010": ("Kepada siapakah Al-Qur'an diturunkan?", ["Nabi Muhammad ﷺ", "Nabi Musa", "Nabi Isa", "Nabi Daud"], "Al-Qur'an diturunkan kepada Nabi Muhammad ﷺ melalui malaikat Jibril."),
"quran_011": ("Apa nama ayat 255 surah Al-Baqarah yang terkenal?", ["Ayat Kursi", "Ayat An-Nur", "Ayat Ash-Shiyam", "Ayat Ad-Dain"], "Ayat 2:255, Ayat Kursi, menggambarkan keagungan Allah: «Allah, tidak ada tuhan selain Dia, Yang Mahahidup…»"),
"quran_012": ("Surah apa yang tidak diawali dengan «Bismillahirrahmanirrahim»?", ["At-Taubah", "Al-Fatihah", "Yasin", "Al-Kahfi"], "At-Taubah (surah 9) adalah satu-satunya surah yang tidak dibuka dengan basmalah."),
"quran_013": ("Apa tema ayat terpanjang dalam Al-Qur'an (2:282)?", ["Pencatatan utang", "Ibadah haji", "Puasa", "Warisan"], "Ayat terpanjang Al-Qur'an mengajarkan mencatat utang dan mengambil saksi: kejujuran dijaga."),
"quran_014": ("Dengan kata apakah ayat-ayat pertama yang diturunkan dimulai?", ["Iqra' (Bacalah!)", "Qul (Katakanlah!)", "Sabbih (Sucikanlah!)", "Kutiba (Telah diwajibkan)"], "Ayat-ayat pertama yang diturunkan dimulai dengan «Iqra'»: «Bacalah dengan nama Tuhanmu yang menciptakan.»"),
"quran_015": ("Menurut Al-Qur'an, Lailatul Qadar lebih baik daripada berapa bulan?", ["Seribu bulan", "Seratus bulan", "Dua belas bulan", "Empat puluh bulan"], "«Lailatul Qadar lebih baik daripada seribu bulan»: satu malam Ramadan yang lebih bernilai daripada ibadah seumur hidup."),
"quran_016": ("Apa sebutan dua surah terakhir, Al-Falaq dan An-Nas, yang dibaca untuk perlindungan?", ["Al-Mu'awwidzatain (dua surah perlindungan)", "Az-Zahrawan", "Al-Mufashshal", "As-Sab' Ath-Thiwal"], "Al-Falaq dan An-Nas disebut «al-mu'awwidzatain»: keduanya dibaca untuk memohon perlindungan Allah."),
"quran_017": ("Menjadi berapa bagian (juz) Al-Qur'an secara tradisional dibagi?", ["30", "10", "60", "114"], "Al-Qur'an dibagi menjadi 30 juz, yang memudahkan mengkhatamkannya dalam sebulan, misalnya selama Ramadan."),
"quran_018": ("Berapa jumlah ayat surah Al-Fatihah?", ["7", "3", "10", "14"], "Al-Fatihah memiliki tujuh ayat, dibaca pada setiap rakaat salat."),
"quran_019": ("Surah apa yang dinamai menurut sebuah logam?", ["Al-Hadid (Besi)", "An-Nur (Cahaya)", "Ar-Ra'd (Guruh)", "Ad-Dukhan (Kabut)"], "Surah 57 bernama Al-Hadid: «Kami turunkan besi yang mempunyai kekuatan hebat dan banyak manfaat bagi manusia.»"),
"quran_020": ("Kisah apa yang disebut Al-Qur'an sebagai «kisah yang paling baik»?", ["Kisah Yusuf", "Kisah Nuh", "Kisah penghuni gua", "Kisah gajah"], "«Kami menceritakan kepadamu kisah yang paling baik»: demikian kisah Yusuf dibuka."),
"quran_021": ("Berapa jumlah ayat Al-Baqarah, surah terpanjang?", ["286", "114", "200", "365"], "Al-Baqarah memiliki 286 ayat, surah terpanjang dalam Al-Qur'an."),
"quran_022": ("Surah pendek apa yang menyatakan: «Katakanlah: Dialah Allah, Yang Maha Esa»?", ["Al-Ikhlas", "Al-Falaq", "An-Nas", "Al-Kautsar"], "Al-Ikhlas menyatakan keesaan Allah yang sempurna dalam empat ayat."),
"quran_023": ("Selama kurang lebih berapa tahun Al-Qur'an diturunkan?", ["23 tahun", "1 tahun", "10 tahun", "40 tahun"], "Al-Qur'an diturunkan secara bertahap selama sekitar 23 tahun, di Makkah lalu di Madinah."),
"quran_024": ("Menurut Al-Qur'an, apa Rumah pertama yang dibangun bagi manusia untuk beribadah kepada Allah?", ["Ka'bah, di Bakkah (Makkah)", "Masjid Quba", "Baitul Maqdis", "Masjid Nabawi ﷺ"], "«Sesungguhnya rumah pertama yang dibangun untuk manusia ialah yang di Bakkah, yang diberkahi…»: Ka'bah di Makkah."),
"quran_025": ("Surah apa yang dinamai menurut gajah?", ["Al-Fil", "An-Nahl", "An-Naml", "Al-Baqarah"], "Surah 105, Al-Fil («Gajah»), mengenang pasukan gajah Abrahah yang dihentikan sebelum mencapai Makkah."),
"quran_026": ("Surah An-Nahl dinamai menurut serangga apa?", ["Lebah", "Semut", "Laba-laba", "Lalat"], "An-Nahl berarti «lebah»; di dalamnya Allah mengilhamkan lebah untuk membuat sarangnya (16:68)."),
"quran_027": ("Surah apa yang dinamai menurut semut?", ["An-Naml", "An-Nahl", "Al-'Ankabut", "Al-An'am"], "An-Naml («Semut», surah 27) mengisahkan semut yang memperingatkan kawan-kawannya saat pasukan Sulaiman mendekat."),
"quran_028": ("Dalam surah Al-'Ankabut, dengan apa Al-Qur'an mengumpamakan orang yang mengambil pelindung selain Allah?", ["Laba-laba yang membuat rumah yang rapuh", "Lebah yang membangun sarangnya", "Semut yang menyimpan makanan", "Anjing yang terengah-engah"], "«Sesungguhnya rumah yang paling lemah ialah rumah laba-laba» (29:41), yang menjadi nama surah ini."),
"quran_029": ("Surah Al-Baqarah dinamai menurut hewan apa?", ["Sapi betina", "Unta", "Kuda", "Domba"], "Al-Baqarah («Sapi Betina») mengenang sapi yang diperintahkan untuk disembelih oleh Bani Israil (2:67)."),
"quran_030": ("Apa arti judul surah 6, Al-An'am?", ["Binatang ternak", "Burung-burung", "Kebun-kebun", "Bintang-bintang"], "Al-An'am berarti «binatang ternak»; surah ini membantah aturan yang dibuat-buat kaum musyrik tentang ternak."),
"quran_031": ("Ayat apa yang diulang berkali-kali dalam surah Ar-Rahman?", ["«Maka nikmat Tuhanmu yang manakah yang kamu dustakan?»", "«Allah Mahabesar»", "«Katakanlah: Dialah Allah, Yang Maha Esa»", "«Segala puji bagi Allah»"], "Ayat ini («Fa-bi-ayyi ala'i rabbikuma tukadzdziban») diulang 31 kali dalam surah 55."),
"quran_032": ("Menurut surah Al-Kahfi, berapa lama penghuni gua tertidur?", ["Tiga ratus tahun ditambah sembilan", "Seratus tahun", "Empat puluh tahun", "Seribu tahun"], "«Mereka tinggal dalam gua selama tiga ratus tahun dan ditambah sembilan tahun» (18:25)."),
"quran_033": ("Hewan apa yang bersama penghuni gua?", ["Anjing", "Kucing", "Keledai", "Kambing"], "«Anjing mereka membentangkan kedua lengannya di depan pintu gua» (18:18)."),
"quran_034": ("Terhadap kaum apa Dzulqarnain membangun tembok, menurut surah Al-Kahfi?", ["Ya'juj dan Ma'juj", "'Ad dan Tsamud", "Bangsa Romawi", "Bangsa Persia"], "Suatu kaum memohon perlindungan darinya terhadap Ya'juj dan Ma'juj; ia membangun tembok dari besi dan tembaga (18:94-96)."),
"quran_035": ("Ayat apa yang dimulai dengan «Allah adalah cahaya langit dan bumi»?", ["Ayat Cahaya (An-Nur 24:35)", "Ayat Kursi", "Ayat Utang", "Ayat Gua"], "«Ayat An-Nur» mengumpamakan cahaya-Nya dengan sebuah lubang yang di dalamnya ada pelita (24:35)."),
"quran_036": ("Menurut hadis dalam Sahih al-Bukhari, surah apa yang setara dengan sepertiga Al-Qur'an?", ["Al-Ikhlas", "Al-Fatihah", "Yasin", "Al-Kahfi"], "Nabi ﷺ bersabda tentang «Qul huwallahu ahad» bahwa ia «setara dengan sepertiga Al-Qur'an»."),
"quran_037": ("Ayat apa yang disebut Nabi ﷺ sebagai ayat paling agung dalam Al-Qur'an, menurut Sahih Muslim?", ["Ayat Kursi", "Ayat pertama Al-Fatihah", "Ayat terakhir Al-Baqarah", "Ayat Cahaya"], "Beliau bertanya kepada Ubay bin Ka'b ayat mana yang paling agung; Ubay menjawab Ayat Kursi, dan Nabi ﷺ memberinya selamat."),
"quran_038": ("Musuh Nabi ﷺ siapakah yang disebut namanya dalam surah Al-Masad?", ["Abu Lahab", "Abu Jahal", "Abu Sufyan", "Al-Walid"], "«Binasalah kedua tangan Abu Lahab» (111:1): paman Nabi ﷺ ini memusuhinya secara terang-terangan."),
"quran_039": ("Bagaimana surah Al-Kafirun diakhiri?", ["«Untukmu agamamu, dan untukku agamaku»", "«Allah Mahabesar»", "«Dan tidak ada sesuatu pun yang setara dengan-Nya»", "«Dari kejahatan orang yang dengki»"], "«Lakum dinukum wa liya din» (109:6) menyatakan pemisahan yang jelas antara Islam dan penyembahan berhala."),
"quran_040": ("Tentang apa surah An-Nashr?", ["Pertolongan Allah dan manusia masuk agama-Nya secara berbondong-bondong", "Penciptaan langit", "Puasa di bulan Ramadan", "Kisah Yusuf"], "«Apabila telah datang pertolongan Allah dan kemenangan, dan engkau melihat manusia berbondong-bondong masuk agama Allah» (110:1-2)."),
"quran_041": ("Menurut surah Al-'Ashr, siapa yang selamat dari kerugian?", ["Orang yang beriman, beramal saleh, dan saling menasihati dalam kebenaran dan kesabaran", "Orang yang kaya", "Orang yang kuat", "Orang yang bepergian"], "«Sungguh, manusia berada dalam kerugian, kecuali orang-orang yang beriman dan mengerjakan kebajikan serta saling menasihati untuk kebenaran dan kesabaran» (103:2-3)."),
"quran_042": ("Dalam surah Al-Ma'un, apa yang dilakukan «orang yang mendustakan hari Pembalasan»?", ["Menghardik anak yatim dan tidak mendorong memberi makan orang miskin", "Merobohkan masjid", "Menolak bepergian", "Berdusta tentang hartanya"], "«Itulah orang yang menghardik anak yatim dan tidak mendorong memberi makan orang miskin» (107:2-3)."),
"quran_043": ("Menurut ayat-ayat pertama yang diturunkan (Al-'Alaq), dari apa Allah menciptakan manusia?", ["Segumpal darah ('alaq)", "Cahaya", "Api", "Angin"], "«Bacalah dengan nama Tuhanmu yang menciptakan, Dia telah menciptakan manusia dari segumpal darah» (96:1-2)."),
"quran_044": ("Apa yang dimaksud ungkapan Al-Qur'an «tujuh ayat yang diulang-ulang» (as-sab' al-matsani)?", ["Al-Fatihah", "Tujuh surah terpanjang", "Ayat Kursi", "Tujuh ayat terakhir Al-Qur'an"], "«Kami telah berikan kepadamu tujuh ayat yang diulang-ulang dan Al-Qur'an yang agung» (15:87): Al-Fatihah, dibaca pada setiap rakaat."),
"quran_045": ("Apa arti «Al-Furqan», salah satu nama Al-Qur'an?", ["Pembeda (antara yang benar dan yang batil)", "Cahaya", "Peringatan", "Penyembuh"], "«Mahasuci Allah yang telah menurunkan Furqan kepada hamba-Nya» (25:1): Kitab yang memisahkan kebenaran dari kebatilan."),
"quran_046": ("Dengan apa Allah bersumpah di awal surah Ath-Thur?", ["Demi bukit (Thur)", "Demi matahari", "Demi buah tin", "Demi malam"], "«Demi bukit! Dan demi Kitab yang ditulis…» (52:1-2): Thur adalah gunung tempat Musa menerima wahyu."),
"quran_047": ("Apa arti «An-Najm», judul surah 53?", ["Bintang", "Bulan", "Matahari", "Fajar"], "«Demi bintang ketika terbenam!» (53:1)."),
"quran_048": ("Menurut surah Al-Qadr, siapa yang turun pada Lailatul Qadar?", ["Para malaikat dan Ruh (Jibril)", "Para nabi", "Para jin", "Angin"], "«Pada malam itu turun para malaikat dan Ruh dengan izin Tuhannya» (97:4)."),
"quran_049": ("Menurut Al-Qur'an, apa Al-Qur'an bagi orang-orang beriman?", ["Penyembuh dan rahmat", "Sekadar syair", "Buku sejarah", "Kalender"], "«Kami turunkan dari Al-Qur'an sesuatu yang menjadi penyembuh dan rahmat bagi orang-orang beriman» (17:82)."),
"quran_050": ("Tantangan apa yang diajukan Al-Qur'an bagi orang yang meragukan asal ilahinya?", ["Membuat satu surah saja yang semisalnya", "Menghafal seluruh Al-Qur'an", "Menerjemahkan Al-Qur'an", "Membangun masjid"], "«Jika kamu meragukan apa yang Kami turunkan, maka buatlah satu surah yang semisal dengannya» (2:23)."),
"quran_051": ("Surah apa yang disebut «Ummul Qur'an» (Induk Al-Qur'an)?", ["Al-Fatihah", "Al-Baqarah", "Yasin", "Al-Ikhlas"], "Nabi ﷺ bersabda: «Ummul Qur'an adalah tujuh ayat yang diulang-ulang dan Al-Qur'an yang agung.»"),
"quran_052": ("Apa yang dimaksud surah «Makkiyah»?", ["Surah yang diturunkan sebelum hijrah", "Surah yang diturunkan di Madinah", "Surah tentang Ka'bah", "Surah yang sangat pendek"], "Para ulama menggolongkan surah berdasarkan masanya: sebelum hijrah ke Madinah (Makkiyah) atau sesudahnya (Madaniyah)."),
"quran_053": ("Berapa surah yang dimulai dengan huruf «Alif, Lam, Mim»?", ["Enam", "Dua", "Sepuluh", "Satu"], "Al-Baqarah, Ali 'Imran, Al-'Ankabut, Ar-Rum, Luqman, dan As-Sajdah dibuka dengan «Alif, Lam, Mim»."),
"quran_054": ("Apa sebutan huruf-huruf terpisah yang membuka beberapa surah (Alif Lam Mim, Yasin, Qaf…)?", ["Huruf-huruf muqaththa'ah", "Ayat-ayat yang dihapus", "Huruf syamsiyah", "Huruf tajwid"], "Dua puluh sembilan surah dibuka dengan huruf-huruf ini, yang makna sepenuhnya hanya diketahui Allah."),
"quran_055": ("Surah apa yang dinamai menurut Nabi Muhammad ﷺ?", ["Surah 47, Muhammad", "Surah 1, Al-Fatihah", "Surah 36, Yasin", "Surah 112, Al-Ikhlas"], "Surah 47 bernama «Muhammad»; namanya disebut pada ayat 2."),
"quran_056": ("Apa nasihat pertama Luqman kepada anaknya yang dikutip dalam Al-Qur'an?", ["Jangan mempersekutukan Allah dengan sesuatu pun", "Pelajari bintang-bintang", "Jadilah pedagang", "Bepergianlah jauh"], "«Wahai anakku, janganlah engkau mempersekutukan Allah; sesungguhnya mempersekutukan Allah adalah benar-benar kezaliman yang besar» (31:13)."),
"quran_057": ("Dengan nama lain apa surah At-Taubah dikenal?", ["Bara'ah (Pemutusan hubungan)", "An-Nur", "Al-Anfal", "Al-Fath"], "Kata pertamanya adalah «Bara'ah»: pernyataan pemutusan hubungan dari Allah dan Rasul-Nya terhadap kaum musyrik (9:1)."),
"quran_058": ("Surah apa yang dimulai dengan dua huruf «Ya, Sin»?", ["Yasin (surah 36)", "Thaha", "Qaf", "Shad"], "Surah 36 dibuka dengan «Yasin. Demi Al-Qur'an yang penuh hikmah!»"),
"quran_059": ("Apa arti «Al-Mulk», judul surah 67?", ["Kerajaan / Kekuasaan", "Cahaya", "Perjalanan", "Kemenangan"], "«Mahasuci Allah yang menguasai segala kerajaan (al-Mulk)» (67:1)."),
"quran_060": ("Apa surah terakhir dalam Al-Qur'an?", ["An-Nas", "Al-Falaq", "Al-Ikhlas", "Al-Fatihah"], "An-Nas («Manusia»), surah 114, menutup Al-Qur'an: «Katakanlah: Aku berlindung kepada Tuhan manusia»."),
"quran_061": ("Bagaimana surah Al-Falaq dimulai?", ["«Katakanlah: Aku berlindung kepada Tuhan yang menguasai subuh»", "«Katakanlah: Dialah Allah, Yang Maha Esa»", "«Demi masa!»", "«Segala puji bagi Allah»"], "«Qul a'udzu birabbil-falaq» (113:1): Al-Falaq berarti waktu subuh."),
"quran_062": ("Dua bukit apa yang disebut Al-Qur'an di antara «syiar-syiar Allah»?", ["Shafa dan Marwah", "Uhud dan Tsur", "Arafah dan Mina", "Hira dan Abu Qubais"], "«Sesungguhnya Shafa dan Marwah merupakan sebagian syiar Allah» (2:158): sa'i dalam ibadah haji dilakukan di antara keduanya."),
"quran_063": ("Siapa satu-satunya perempuan yang disebut namanya dalam Al-Qur'an?", ["Maryam", "Khadijah", "Asiyah", "Hajar"], "Maryam, ibu Isa, disebut dalam beberapa surah, dan satu surah utuh menyandang namanya."),
"quran_064": ("Siapa satu-satunya sahabat Nabi ﷺ yang disebut namanya dalam Al-Qur'an?", ["Zaid bin Haritsah", "Abu Bakar", "Umar", "Ali"], "«Maka ketika Zaid telah mengakhiri keperluan terhadap istrinya…» (33:37): Zaid, bekas budak yang dimerdekakan Nabi, satu-satunya sahabat yang disebut namanya."),
"quran_065": ("Siapakah Harut dan Marut yang disebut dalam surah Al-Baqarah?", ["Dua malaikat yang diutus ke Babilonia", "Dua nabi", "Dua raja Mesir", "Dua sahabat"], "«…apa yang diturunkan kepada dua malaikat di negeri Babilonia, yaitu Harut dan Marut» (2:102): keduanya memperingatkan bahwa sihir adalah ujian."),
"quran_066": ("Menurut Al-Qur'an, siapa yang paling mulia di sisi Allah?", ["Yang paling bertakwa", "Yang paling kaya", "Yang paling kuat", "Yang paling terkenal"], "«Sesungguhnya yang paling mulia di antara kamu di sisi Allah ialah orang yang paling bertakwa» (49:13)."),
"quran_067": ("Apa yang dimaksud «Al-Waqi'ah», judul surah 56?", ["Peristiwa yang pasti terjadi (hari Kiamat)", "Kafilah", "Semut", "Perjalanan malam"], "«Apabila terjadi hari Kiamat…» (56:1): surah ini menggambarkan tiga golongan manusia pada hari Akhir."),
"quran_068": ("Dengan benda apa Allah bersumpah di awal surah Al-Qalam?", ["Demi pena", "Demi pedang", "Demi timbangan", "Demi pelita"], "«Nun. Demi pena dan apa yang mereka tuliskan!» (68:1)."),
"quran_069": ("Bagaimana surah Al-Fajr dibuka?", ["Dengan sumpah demi fajar dan sepuluh malam", "Dengan sumpah demi buah tin", "Dengan kisah Yusuf", "Hanya dengan basmalah"], "«Demi fajar! Dan demi malam yang sepuluh!» (89:1-2)."),
"quran_070": ("Dengan benda langit apa Allah bersumpah di awal surah Asy-Syams?", ["Matahari", "Bulan saja", "Bintang-bintang", "Planet-planet"], "«Demi matahari dan sinarnya pada pagi hari!» (91:1); Asy-Syams berarti «matahari»."),
"quran_071": ("Surah apa yang dibuka dengan: «Bukankah pernah datang kepada manusia waktu dari masa, yang ketika itu belum merupakan sesuatu yang dapat disebut?»", ["Al-Insan (surah 76)", "Al-Kahfi", "Al-Hajj", "Al-Fatihah"], "Al-Insan («Manusia»), juga disebut Ad-Dahr, mengingatkan bahwa manusia bukan apa-apa sebelum diciptakan (76:1)."),
"quran_072": ("Menurut Al-Qur'an, untuk apa Allah memudahkan Al-Qur'an?", ["Untuk diingat dan dihafal", "Untuk berdagang", "Untuk diterjemahkan", "Untuk dilupakan"], "«Sungguh, telah Kami mudahkan Al-Qur'an untuk peringatan, maka adakah orang yang mau mengambil pelajaran?» (54:17), diulang empat kali dalam surah ini."),
"quran_073": ("Tanda apa yang disebut surah Al-Qamar pada ayat pertamanya?", ["Bulan terbelah", "Matahari padam", "Laut terbelah", "Gunung berbicara"], "«Saat (hari Kiamat) semakin dekat, bulan pun terbelah» (54:1): tanda yang diperlihatkan kepada penduduk Makkah."),
"quran_074": ("Mengapa Al-Qur'an diturunkan secara bertahap dan tidak sekaligus, menurut Al-Qur'an sendiri?", ["Untuk meneguhkan hati Nabi ﷺ", "Karena terlalu panjang", "Untuk menyembunyikannya dari musuh", "Karena perjalanan"], "«Demikianlah, agar Kami memperteguh hatimu dengannya dan Kami membacakannya secara tartil» (25:32)."),
"quran_075": ("Surah apa yang dibaca Nabi ﷺ ke dalam kedua tangannya setiap malam sebelum tidur, menurut Aisyah?", ["Al-Ikhlas, Al-Falaq, dan An-Nas", "Al-Fatihah dan Al-Baqarah", "Yasin dan Al-Mulk", "Al-Kahfi dan Maryam"], "Beliau meniup kedua tangannya sambil membaca tiga surah «Qul», lalu mengusapkannya ke tubuhnya, tiga kali."),
"quran_076": ("Apa sebutan sujud yang dilakukan ketika membaca ayat-ayat tertentu dalam Al-Qur'an?", ["Sujud tilawah", "Sujud sahwi", "Sujud syukur", "Rukuk"], "Al-Qur'an memuat ayat-ayat sajdah, seperti ayat terakhir Al-'Alaq: «sujudlah dan dekatkanlah dirimu» (96:19)."),
"quran_077": ("Apa nama ilmu tentang kaidah melafalkan Al-Qur'an dengan benar?", ["Tajwid", "Tafsir", "Fikih", "Sirah"], "Tajwid mengajarkan cara melafalkan setiap huruf dari makhrajnya, beserta sifat-sifatnya."),
"quran_078": ("Apa sebutan orang yang telah menghafal seluruh Al-Qur'an?", ["Hafiz", "Imam", "Muazin", "Mufti"], "Hafiz berarti «penjaga»: ia membawa seluruh Al-Qur'an dalam ingatannya."),
"quran_079": ("Apa sebutan salinan tertulis Al-Qur'an?", ["Mushaf", "Hadis", "Juz", "Mimbar"], "Mushaf adalah Al-Qur'an yang dihimpun di antara dua sampul; juz adalah salah satu dari tiga puluh bagiannya."),
"quran_080": ("Dalam surah apa basmalah muncul dua kali?", ["An-Naml", "Al-Fatihah", "At-Taubah", "Al-Baqarah"], "Selain pada pembukaannya, An-Naml mengutip basmalah di awal surat Sulaiman kepada ratu Saba' (27:30)."),
}
